            Object response = (this.v2PrivatePostAccountDepositAddress(parameters)).join();
            //
            //     {
            //         "result": "success",
            //         "errorCode": "0",
            //         "walletAddress": {
            //             "matic": null,
            //             "btc": "mnobqu4i6qMCJWDpf5UimRmr8JCvZ8FLcN",
            //             "xrp": null,
            //             "xrp_tag": "-1",
            //             "kava": null,
            //             "kava_memo": null,
            //         }
            //     }
